        return None


def _loudnorm_value(stats: Optional[Dict[str, Any]], key: str, default: float) -> str:
    if not stats:
        return str(default)
    value = _clean_text(stats.get(key))
    if not value or value.lower() in {"nan", "-inf", "inf"}:
        return str(default)
    return value


