            _set_step(max(0, len(pattern) - quarter_step), True)
            _set_step(max(0, len(pattern) - 2), True)
        elif resolved_role == "kick":
            _set_step(max(0, len(pattern) - quarter_step), True)
        elif resolved_role == "bass":
            pattern = [False] * len(pattern)
